using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo.Variables;

[CreateAssetMenu(menuName = "Variables References/Float Reference")]
public class FloatReference : GameEvent<float>
{
	[Header("Variable")]
	[SerializeField]
	private bool externalSet;

	[SerializeField]
	[HideIf("externalSet")]
	private float value;

	public float Value => value;

	public void SetValue(float value)
	{
		if (externalSet)
		{
			this.value = value;
			Raise(value);
		}
		else
		{
			Debug.Log($"Cannot set {base.name} from external source, because bool externalSet is false");
		}
	}
}
